(select to_jsonb(t) from public.editions t where t.id=987260002)='{"id":987260002,"title":"14 juli","isbn_10":null,"isbn_13":"9789029092722","work_id":987160002,"cover_id":13214322,"language":"dut","publisher":"Meulenhoff","publish_date":null,"open_library_edition_id":"OL46533679M"}'::jsonb as exact union all select 'catalog_work_descriptions:9' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987160002 and t.language='nl')='{"text":"In het Parijs van 1789 nemen honger en onvrede toe, terwijl fabrikanten op de lonen willen bezuinigen. Éric Vuillard volgt de mensen die zich op straat verzamelen en uiteindelijk bij de Bastille terechtkomen. Zijn aandacht gaat naar ambachtslieden, arbeiders en andere deelnemers die in grote geschiedverhalen nauwelijks een naam krijgen. Vanuit hun levens reconstrueert hij de aanloop naar 14 juli en de onrust van die dag. Het boek verbindt historische gegevens met een literaire verbeelding van de menigte.","work_id":987160002,"evidence":[{"note":"DistinctVuillard2016Frenchoriginal14juillet and exactDutchHardcover9789029092722 translatedLiesbethvanNes2019. FreshpublicAPI parentOL20934335W andauthorOL1450411A agree; staleindexedHTMLdifferentparent isnotfollowed. Libraryoriginaltitle andprimaryMeulenhoffcontent confirm samebook; noGoncourtclaimforthisbook.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p422375888"],"reference":"new-work-dossier-readings-061.json#210","checked_at":"2026-11-03T12:14:47.005Z"},{"type":"original_substantive_source_review","review":"content-amendment-026.json","sources":["https://www.lannoo.com/nl-nl/literatuur-romans/14-juli-9789402311242","https://www.bibliotheek.nl/catalogus/titel.422375888.html/14-juli/","https://www.tzum.info/2019/09/recensie-eric-vuillard-14-juli/","https://openlibrary.org/works/OL20934335W","https://data.bibliotheken.nl/id/nbt/p422375888"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existi